def build_homepage(search_index):
    grid = '\n'.join(
        f'''<a class="cat-card" href="/{c['slug']}/">
  <div class="icon">{c['icon']}</div>
  <h3>{c['title']}</h3>
  <p>{c['desc'][:80]}...</p>
</a>''' for c in TAXONOMY
    )

    # Featured products (up to 8 from populated leaves)
    featured = []
    for cat in TAXONOMY:
        for sub in cat['subcategories']:
            for leaf in sub['leaves']:
                prods = leaf.get('products', [])
                if prods:
                    p = prods[0]
                    url = f"/{cat['slug']}/{sub['slug']}/{leaf['slug']}/"
                    featured.append((p, leaf['title'], url))
                if len(featured) >= 8:
                    break
            if len(featured) >= 8:
                break
        if len(featured) >= 8:
            break

    feat_html = ""
    if featured:
        cards = '\n'.join(f'''<a class="feat-card" href="{url}">
  <img src="{IMG_BASE}/{p['img']}._AC_SL200_.jpg" alt="{p['name']}" loading="lazy" width="140" height="140">
  <div class="feat-info">
    <span class="feat-cat">{cat_title}</span>
    <h4>{p['name']}</h4>
  </div>
</a>''' for p, cat_title, url in featured)
        feat_html = f"""
<section class="featured-section">
  <div class="container">
    <h2 class="section-title">Top Picks This Week</h2>
    <div class="feat-grid">{cards}</div>
  </div>
</section>"""

    si_json = json.dumps(search_index)
    body = f"""
{nav_html()}
<section class="hero">
  <div class="hero-inner">
    <h1>What Are The Best Products?</h1>
    <p>Expert reviews and honest comparisons across {sum(len(s['leaves']) for c in TAXONOMY for s in c['subcategories'])}+ categories. We research so you don't have to.</p>
    <div class="hero-search">
      <input type="search" id="hero-search" placeholder="Try: best air fryers, gaming chairs..." autocomplete="off">
      <button onclick="doSearch()">Search</button>
    </div>
  </div>
</section>
<section class="main-section">
  <div class="container">
    <h2 class="section-title mt-2">Browse All Categories</h2>
    <div class="main-cat-grid">{grid}</div>
  </div>
</section>
{feat_html}
<style>
.featured-section{{background:var(--bg-alt);padding:2rem 0;margin-top:2rem}}
.feat-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:1rem;margin-top:1rem}}
.feat-card{{display:flex;flex-direction:column;gap:0.5rem;background:#fff;border:1px solid var(--border);border-radius:var(--radius);padding:1rem;text-decoration:none;color:var(--text);transition:box-shadow .15s}}
.feat-card:hover{{box-shadow:0 4px 16px rgba(0,0,0,.1);text-decoration:none}}
.feat-card img{{width:100px;height:100px;object-fit:contain;margin:0 auto}}
.feat-info{{text-align:center}}
.feat-cat{{font-size:0.7rem;text-transform:uppercase;color:var(--primary);font-weight:700;letter-spacing:.5px}}
.feat-info h4{{font-size:0.875rem;font-weight:600;margin:0.25rem 0}}

</style>
"""
    title = f"WhatAreBest.com  -  Expert Product Reviews & Best-Of Guides {YEAR}"
    desc = f"Independent product reviews and comparisons across 500+ categories. Find the best air fryers, robot vacuums, tools, fitness equipment, and more."
    html = page_shell(title, desc, "/", body, si_json)
    (SITE_DIR / "index.html").write_text(html)
    print(f"  ✅ Homepage")


def build_main_cat_page(cat, search_index):
    crumbs = [(cat['title'], f"/{cat['slug']}/")]
    sub_cards = ""
    for sub in cat['subcategories']:
        links = '\n'.join(
            f'<li><a href="/{cat["slug"]}/{sub["slug"]}/{leaf["slug"]}/">{leaf["title"]}</a></li>'
            for leaf in sub['leaves']
        )
        sub_cards += f"""<div class="subcat-card">
  <h3><a href="/{cat['slug']}/{sub['slug']}/">{sub['title']}</a></h3>
  <ul>{links}</ul>
</div>"""

    si_json = json.dumps(search_index)
    body = f"""
{nav_html(crumbs)}
<div class="page-header">
  <div class="page-header-inner">
    <h1>{cat['icon']} {cat['title']}</h1>
    <p>{cat['desc']}</p>
  </div>
</div>
<div class="container">
  <div class="subcat-grid" style="padding-top:1.5rem">{sub_cards}</div>
</div>"""

    title = f"Best {cat['title']}  -  Reviews, Rankings & Buying Guides | WhatAreBest"
    html = page_shell(title, cat['desc'], f"/{cat['slug']}/", body, si_json)
    out = SITE_DIR / cat['slug']
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(html)
    print(f"  ✅ Main cat: /{cat['slug']}/")


