def build_leaf_page(cat, sub, leaf, search_index, all_leaves_in_sub):
    path = f"/{cat['slug']}/{sub['slug']}/{leaf['slug']}/"
    crumbs = [
        (cat['title'], f"/{cat['slug']}/"),
        (sub['title'], f"/{cat['slug']}/{sub['slug']}/"),
        (leaf['title'], path),
    ]

    prods = leaf.get('products', [])
    si_json = json.dumps(search_index)

    if not prods:
        # Coming-soon stub  -  still SEO-indexable
        body = f"""
{nav_html(crumbs)}
<div class="page-header">
  <div class="page-header-inner">
    <h1>{leaf['title']}</h1>
    <p>{leaf.get('desc','')}</p>
  </div>
</div>
<div class="coming-soon-box">
  <h1>Full guide coming soon!</h1>
  <p>Our editorial team is currently testing and comparing the best options. Check back soon for our full ranked list.</p>
  <a href="/{cat['slug']}/{sub['slug']}/">← Back to {sub['title']}</a>
</div>"""
        title = f"{leaf['title']}  -  Buying Guide {YEAR} | WhatAreBest"
        desc = leaf.get('desc', f"Expert rankings of {leaf['title'].lower()}  -  updated for {YEAR}.")
        html = page_shell(title, desc, path, body, si_json)
        out = SITE_DIR / cat['slug'] / sub['slug'] / leaf['slug']
        out.mkdir(parents=True, exist_ok=True)
        (out / "index.html").write_text(html)
        return

    # Full review page
    # Validate brands
    for p in prods:
        if p.get('vendor') in BANNED_BRANDS:
            raise ValueError(f"BANNED BRAND {p['vendor']} in {path}")

    # Build product cards
    prod_cards = ""
    for i, p in enumerate(prods):
        badge = p.get('badge', f"#{i+1} Pick")
        is_top = i == 0
        card_cls = "product-card top-pick" if is_top else "product-card"
        data_badge = f' data-badge="{badge}"' if is_top else ''

        pros_html = ''.join(f'<li>{x}</li>' for x in p.get('pros', []))
        cons_html = ''.join(f'<li>{x}</li>' for x in p.get('cons', []))

        prod_cards += f"""<div class="{card_cls}"{data_badge}>
  <div class="product-img-wrap">
    <img src="{IMG_BASE}/{p['img']}._AC_SL300_.jpg" alt="{p['name']}" width="140" height="140" loading="{'eager' if i==0 else 'lazy'}">
  </div>
  <div class="product-body">
    <h3>{p['name']}</h3>
    <div class="product-meta">
      <span class="stars">★ {p.get('stars','4.5')}</span>
      <span class="badge-inline" style="font-size:.75rem;background:var(--bg-alt);padding:.1rem .4rem;border-radius:4px">{badge}</span>
    </div>
    <p class="product-desc">{p.get('desc','')}</p>
    <div class="pros-cons">
      <div class="pros"><h4>Pros</h4><ul>{pros_html}</ul></div>
      <div class="cons"><h4>Cons</h4><ul>{cons_html}</ul></div>
    </div>
    <a class="btn-amazon" href="{AMZ_BASE}/{p['asin']}?tag={TAG}" target="_blank" rel="noopener">
      View on Amazon ↗
    </a>
  </div>
</div>"""

    # Sidebar  -  related leaves in same subcat
    related = [l for l in all_leaves_in_sub if l['slug'] != leaf['slug']][:8]
    related_links = ''.join(
        f'<li><a href="/{cat["slug"]}/{sub["slug"]}/{l["slug"]}/">{l["title"]}</a></li>'
        for l in related
    )
    sidebar = f"""
<div class="sidebar-widget">
  <h4>Related Guides in {sub['title']}</h4>
  <ul>{related_links}</ul>
</div>
<div class="sidebar-widget">
  <h4>Browse {cat['title']}</h4>
  <ul>{''.join(f'<li><a href="/{cat["slug"]}/{s["slug"]}/">{s["title"]}</a></li>' for s in cat["subcategories"])}</ul>
</div>"""

    # JSON-LD for first product
    p0 = prods[0]
    schema = json.dumps({
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": leaf['title'],
        "description": leaf.get('desc', ''),
        "url": f"{SITE_URL}{path}",
        "author": {"@type": "Organization", "name": "WhatAreBest.com"},
        "publisher": {"@type": "Organization", "name": "WhatAreBest.com", "url": SITE_URL},
        "dateModified": f"{YEAR}-01-01",
    }, indent=2)

    body = f"""
{nav_html(crumbs)}
<div class="page-header">
  <div class="page-header-inner">
    <h1>{leaf['title']}</h1>
    <p class="text-muted text-sm">Updated {YEAR} · {len(prods)} picks reviewed</p>
  </div>
</div>
<div class="leaf-layout">
  <main class="leaf-main">
    <p class="page-intro">{leaf.get('intro', leaf.get('desc', ''))}</p>
    <h2 class="section-title">Our Top Picks</h2>
    <div class="product-grid">{prod_cards}</div>
  </main>
  <aside class="leaf-sidebar">{sidebar}</aside>
</div>"""

    title = f"{leaf['title']}  -  Expert Picks {YEAR} | WhatAreBest"
    desc = leaf.get('desc', f"Expert rankings of {leaf['title'].lower()}  -  updated for {YEAR}.")
    extra_head = f'<script type="application/ld+json">{schema}</script>'
    html = page_shell(title, desc, path, body, si_json, extra_head)
    out = SITE_DIR / cat['slug'] / sub['slug'] / leaf['slug']
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(html)


def build_search_page(search_index):
    si_json = json.dumps(search_index)
    body = f"""
{nav_html()}
<div class="page-header">
  <div class="page-header-inner">
    <h1>Search Results</h1>
  </div>
</div>
<div id="search-results" class="container mt-2"><p>Searching...</p></div>"""
    html = page_shell("Search  -  WhatAreBest.com", "Search product reviews and buying guides.", "/search/", body, si_json)
    out = SITE_DIR / "search"
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(html)


def build_sitemap(all_urls):
    xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
    xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    for url, priority in all_urls:
        xml += f'  <url><loc>{SITE_URL}{url}</loc><priority>{priority}</priority></url>\n'
    xml += '</urlset>'
    (SITE_DIR / "sitemap.xml").write_text(xml)
    print(f"  ✅ sitemap.xml ({len(all_urls)} URLs)")


def build_robots():
    (SITE_DIR / "robots.txt").write_text(
        f"User-agent: *\nAllow: /\nSitemap: {SITE_URL}/sitemap.xml\n"
    )


def build_404():
    body = f"""
{nav_html()}
<div class="coming-soon-box">
  <h1>Page Not Found</h1>
  <p>The page you're looking for doesn't exist.</p>
  <a href="/">← Back to Home</a>
</div>"""
    (SITE_DIR / "404.html").write_text(
        page_shell("Page Not Found | WhatAreBest.com", "Page not found.", "/404.html", body, "[]")
    )


