# MAIN
# ─────────────────────────────────────────────────────────────────────────────

def build_all(only_cat=None):
    SITE_DIR.mkdir(parents=True, exist_ok=True)

    # Build search index
    search_index = []
    all_urls = [("/", "1.0"), ("/search/", "0.3")]

    for cat in TAXONOMY:
        if only_cat and cat['slug'] != only_cat:
            continue
        all_urls.append((f"/{cat['slug']}/", "0.9"))
        search_index.append({
            "title": cat['title'],
            "url": f"/{cat['slug']}/",
            "desc": cat['desc'][:120],
            "cat": cat['title'],
        })
        for sub in cat['subcategories']:
            all_urls.append((f"/{cat['slug']}/{sub['slug']}/", "0.8"))
            search_index.append({
                "title": sub['title'],
                "url": f"/{cat['slug']}/{sub['slug']}/",
                "desc": sub['desc'][:120],
                "cat": cat['title'],
            })
            for leaf in sub['leaves']:
                url = f"/{cat['slug']}/{sub['slug']}/{leaf['slug']}/"
                all_urls.append((url, "0.7"))
                search_index.append({
                    "title": leaf['title'],
                    "url": url,
                    "desc": leaf.get('desc', '')[:120],
                    "cat": f"{cat['title']} › {sub['title']}",
                })

    si_json = json.dumps(search_index)

    total_pages = 0
    total_products = 0

    for cat in TAXONOMY:
        if only_cat and cat['slug'] != only_cat:
            continue
        print(f"\n🗂️  {cat['title']}")
        build_main_cat_page(cat, search_index)
        total_pages += 1

        for sub in cat['subcategories']:
            build_subcat_page(cat, sub, search_index)
            total_pages += 1

            for leaf in sub['leaves']:
                build_leaf_page(cat, sub, leaf, search_index, sub['leaves'])
                n_prods = len(leaf.get('products', []))
                total_pages += 1
                total_products += n_prods

    build_homepage(search_index)
    build_search_page(search_index)
    build_robots()
    build_404()

    if not only_cat:
        build_sitemap(all_urls)

    print(f"\n{'='*50}")
    print(f"✅ Built {total_pages} pages, {total_products} products")
    print(f"   Site dir: {SITE_DIR}")
    print(f"   Sitemap: {len(all_urls)} URLs")
    print(f"   Coming-soon stubs: {total_pages - total_products} pages ready to fill")


def verify_images():
    import urllib.request
    print("Verifying product image hashes...")
    ok = fail = 0
    for cat in TAXONOMY:
        for sub in cat['subcategories']:
            for leaf in sub['leaves']:
                for p in leaf.get('products', []):
                    url = f"{IMG_BASE}/{p['img']}._AC_SL400_.jpg"
                    try:
                        r = urllib.request.urlopen(url, timeout=10)
                        size = len(r.read())
                        if size < 1000:
                            print(f"  ❌ TOO SMALL {size}b  -  {leaf['slug']}/{p['vendor']}: {p['img']}")
                            fail += 1
                        else:
                            print(f"  ✅ {size:,}b  -  {leaf['slug']}/{p['vendor']}: {p['img']}")
                            ok += 1
                    except Exception as e:
                        print(f"  ❌ ERROR  -  {leaf['slug']}/{p['vendor']}: {p['img']} ({e})")
                        fail += 1
    print(f"\n✅ {ok} images OK   ❌ {fail} images FAILED")
    if fail: raise SystemExit(1)


def show_stats():
    total_leaves = sum(len(s['leaves']) for c in TAXONOMY for s in c['subcategories'])
    populated = sum(1 for c in TAXONOMY for s in c['subcategories'] for l in s['leaves'] if l.get('products'))
    total_products = sum(len(l.get('products',[])) for c in TAXONOMY for s in c['subcategories'] for l in s['leaves'])
    total_pages = len(TAXONOMY) + sum(len(c['subcategories']) for c in TAXONOMY) + total_leaves + 3  # +3 for home/search/404
    print(f"Main categories:    {len(TAXONOMY)}")
    print(f"Subcategories:      {sum(len(c['subcategories']) for c in TAXONOMY)}")
    print(f"Leaf categories:    {total_leaves}")
    print(f"Populated leaves:   {populated}")
    print(f"Coming-soon stubs:  {total_leaves - populated}")
    print(f"Total products:     {total_products}")
    print(f"Total pages:        {total_pages}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--verify-images", action="store_true")
    parser.add_argument("--stats", action="store_true")
    parser.add_argument("--only", help="Only build one main category slug")
    args = parser.parse_args()
    if args.verify_images:
        verify_images()
    elif args.stats:
        show_stats()
    else:
        build_all(only_cat=args.only)
